command:
set -euo pipefail
echo ===SERVICE===
systemctl --user is-active frankenstein-local-bridge.service || true
systemctl --user show frankenstein-local-bridge.service -p MainPID -p ActiveState -p SubState || true
echo ===DAEMON_SOURCE_SELECTION===
grep -nE 'sqlite|processed|command_id|glob|commands|receipt|fetch|checkout|for .*json|sorted|rglob' local_bridge_daemon.py | head -220 || true
echo ===DB_CANDIDATES===
find local_bridge_state -maxdepth 2 -type f \( -name '*.db' -o -name '*.sqlite' -o -name '*.sqlite3' \) -print -exec ls -l {} \; 2>/dev/null || true
echo ===IDS_IN_LOCAL_STATE===
grep -R -n -E 'go-avatar-gpt56sol-eye-semantic-live-promote-20260912-0810|0000-go-avatar-eye-semantic-priority-20260912-0802' local_bridge_state 2>/dev/null | head -80 || true
echo ===CURRENT_CONTROL_HEAD===
git -C local_bridge_state/repo rev-parse HEAD || true
git -C local_bridge_state/repo log -1 --format='%H %cI %s' || true
echo SCOPE=READ_ONLY_BRIDGE_DISPATCH_DIAGNOSTIC
